using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class CaptureRolePrefabRawTexture {
 static string folder;static GameObject stage,actor;static Camera camera;static RenderTexture rt;static Animator animator;static int index,waitFrame,lastFrame=-1;static Queue<(string id,string state,float phase)> jobs;static List<object> rows;
 static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});
 public static object Main(string output,string ids){if(!EditorApplication.isPlaying)throw new Exception("Play required");folder=output;Directory.CreateDirectory(folder);rows=new();jobs=new();foreach(var id in ids.Split(',')){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/"+id+"/"+id+".prefab");var clips=prefab.GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips;foreach(var state in new[]{"idle","walk","attack_once","die","dribble"})if(clips.Any(c=>c.name==state))foreach(float phase in new[]{0f,.25f,.5f,.75f})jobs.Enqueue((id,state,phase));}stage=new GameObject("Temporary role art frame review");stage.transform.position=Vector3.zero;rt=new RenderTexture(768,768,24);var cg=new GameObject("Temporary role review camera");cg.transform.SetParent(stage.transform,false);camera=cg.AddComponent<Camera>();camera.enabled=false;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.35f,.38f);camera.orthographic=true;camera.orthographicSize=1.45f;camera.nearClipPlane=.1f;camera.farClipPlane=25;camera.targetTexture=rt;cg.transform.localPosition=new Vector3(2.9f,2.05f,5);cg.transform.LookAt(stage.transform.position+Vector3.up*1.05f);index=0;waitFrame=-1;EditorApplication.update+=Tick;return new{folder,frames=jobs.Count,pending=true};}
 static void Tick(){if(Time.frameCount==lastFrame)return;lastFrame=Time.frameCount;try{if(jobs.Count==0){Finish(null);return;}var job=jobs.Peek();if(waitFrame<0){if(actor==null||actor.name!=job.id){if(actor!=null)Object.DestroyImmediate(actor);actor=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/"+job.id+"/"+job.id+".prefab"),stage.transform);actor.name=job.id;actor.transform.localPosition=Vector3.zero;foreach(var t in actor.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;foreach(var renderer in actor.GetComponentsInChildren<SkinnedMeshRenderer>()){renderer.quality=SkinQuality.Bone4;var materials=renderer.sharedMaterials.Select(m=>{var copy=new Material(Shader.Find("Universal Render Pipeline/Unlit"));var raw=new Texture2D(2,2,TextureFormat.RGBA32,false);raw.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(m.GetTexture("_BaseMap"))));raw.filterMode=FilterMode.Bilinear;copy.SetTexture("_BaseMap",raw);copy.SetColor("_BaseColor",Color.white);return copy;}).ToArray();renderer.materials=materials;}animator=actor.GetComponentInChildren<Animator>();animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.applyRootMotion=false;animator.speed=0;}animator.Play(job.state,0,job.phase);animator.Update(0);waitFrame=Time.frameCount+2;return;}if(Time.frameCount<waitFrame)return;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(768,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,768,768),0,0);png.Apply();string file=job.id+"-"+job.state+"-"+job.phase.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png";File.WriteAllBytes(Path.Combine(folder,file),png.EncodeToPNG());Object.DestroyImmediate(png);RenderTexture.active=old;rows.Add(new{job.id,job.state,job.phase,file,frame=Time.frameCount});jobs.Dequeue();waitFrame=-1;index++;}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string error){EditorApplication.update-=Tick;if(stage!=null)Object.DestroyImmediate(stage);if(rt!=null){rt.Release();Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(folder,"result.json"),Json(new{completed=error==null,error,frames=rows,conditions="Actual Unity Play; own Animator/controller; wait two rendered frames after each pose. Isolated asset review, not ordinary gameplay."}));}
}
